--
-- sql/lib/design_head.sql -- the quiet / dashboard design, <head> part.
--
-- @@-included by awr_trend.sql right after sql/_style.sql when the design
-- substitution variable is quiet or dashboard (design_head; the classic
-- design includes the empty sql/lib/no_design.sql instead).  Emits the
-- embedded Geist / Geist Mono @font-face rules (sql/lib/css_fonts.plsql,
-- generated by tools/fonts2plsql.sh) and the design stylesheet
-- (sql/lib/css_design.plsql, generated from sql/lib/src/css_design.css),
-- both after the classic <style>, so they override it.  The script half
-- is sql/lib/design_tail.sql.  Nested @@ paths resolve against the driver.
--
@@sql/lib/css_fonts.plsql
@@sql/lib/css_design.plsql
